// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./JudgeContract.sol";
import "./RoleToken.sol";
import "./RegisterContract.sol";

contract GovernanceToken {
    JudgeContract public judgeContract;
    RoleBasedAccessControl public roleBasedAccess;
    RoleToken public roleToken;

    constructor(address _judgeContract, address _roleBasedAccess, address _roleToken) {
        judgeContract = JudgeContract(_judgeContract);
        roleBasedAccess = RoleBasedAccessControl(_roleBasedAccess);
        roleToken = RoleToken(_roleToken);
    }

    // Calculate compliance for a peer
    function getCompliance(address peer) public view returns (uint256) {
        uint256 rewards = judgeContract.getTotalRewards(peer);
        uint256 penalties = judgeContract.getTotalPenalties(peer);

        if (rewards + penalties == 0) {
            return 0; // Avoid division by zero
        }
        return (rewards * 1e18) / (rewards + penalties); // scaled by 1e18 for precision
    }

    // Get status multiplier s_i
    function getStatusMultiplier(address peer) public view returns (uint256) {
        RoleToken.Member memory member = roleBasedAccess.getMember(peer);

        if (keccak256(bytes(member.status)) == keccak256(bytes("BENIGN"))) {
            return 2;
        } else if (keccak256(bytes(member.status)) == keccak256(bytes("SUSPICIOUS"))) {
            return 1;
        } else if (keccak256(bytes(member.status)) == keccak256(bytes("MALICIOUS"))) {
            return 0;
        }
        return 0;
    }

    // Governance power formula
    function getGovernancePower(address peer) external view returns (uint256) {
        uint256 tokenBalance = roleToken.balanceOf(peer);
        uint256 compliance = getCompliance(peer); // scaled 1e18
        uint256 multiplier = getStatusMultiplier(peer);

        // C_total(t) = [Token Balance × (Compliance × 100)] × s_i
        uint256 compliancePercent = (compliance * 100) / 1e18;

        return (tokenBalance * compliancePercent * multiplier);
    }
}
